package com.smartsociety.platform.audit; import com.smartsociety.platform.auth.User; import jakarta.persistence.*; import java.time.Instant; @Entity @Table(name="audit_logs") public class AuditLog{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="actor_id")User actor;@Column(nullable=false)String action;String entityType;String entityId;@Column(columnDefinition="jsonb")String metadata;Instant createdAt=Instant.now();public void setActor(User x){actor=x;}public void setAction(String x){action=x;}public void setEntityType(String x){entityType=x;}public void setEntityId(String x){entityId=x;}public void setMetadata(String x){metadata=x;}}